{"content":"const fs=require('fs');
const {execSync}=require('child_process');
const synText=fs.readFileSync('synonyms.txt','utf8').split(/\r?\n/).filter(l=>l.trim());
const fams=synText.map(l=>l.split(',').map(s=>s.trim()));
const famMap=new Map(); // lower -> fam idx
fams.forEach((parts,i)=>{parts.forEach(p=>{let k=p.toLowerCase(); if(!famMap.has(k)) famMap.set(k,i); else { /* multiple? keep first */ } });});
// also need variant list per fam
function getVariants(wordLower){
  let idx=famMap.get(wordLower);
  if(idx===undefined) return null;
  return {idx, vars:fams[idx]};
}
const baseText=fs.readFileSync('input.base.tex','utf8');

function getOverfulls(text){
  fs.writeFileSync('input.tex',text);
  try{execSync('pdflatex -interaction=nonstopmode main.tex > /dev/null 2>&1');}catch(e){}
  let log='';
  try{log=fs.readFileSync('main.log','utf8');}catch(e){return {count:99, excess:9999, details:''};}
  let lines=log.split(/\n/);
  let over=lines.filter(l=>/Overfull/.test(l));
  let excess=0;
  over.forEach(l=>{let m=l.match(/\(([0-9.]+)pt too wide\)/); if(m) excess+=parseFloat(m[1]);});
  return {count:over.length, excess, details:over.join('\n')};
}

function findOccurrences(text){
  const re=/[A-Za-z]+(?:'[A-Za-z]+)?/g;
  let m; let occs=[];
  while((m=re.exec(text))){
    let w=m[0];
    let low=w.toLowerCase();
    if(famMap.has(low)){
      // determine paragraph index
      let before=text.slice(0,m.index);
      let paraIdx=(before.match(/\n\n/g)||[]).length;
      occs.push({word:w, low, index:m.index, len:w.length, para:paraIdx, famIdx:famMap.get(low), vars:fams[famMap.get(low)]});
    }
  }
  return occs;
}

let baseScore=getOverfulls(baseText);
console.log('BASE',baseScore);

// focus paras
let occs=findOccurrences(baseText);
console.log('total occs',occs.length);
let targetParas=[2,6]; // para indices with overfulls (0-based split by \n\n)
let cands=occs.filter(o=>targetParas.includes(o.para));
console.log('cands in target paras',cands.length);
cands.forEach((o,i)=>console.log(i, JSON.stringify(o.word), 'para'+o.para, 'fam'+JSON.stringify(o.vars)));

// brute force single replacements in target paras
let results=[];
for(let i=0;i<cands.length;i++){
  let o=cands[i];
  for(let v of o.vars){
    // skip if same (case-insensitive? case-sensitive?)
    if(v===o.word) continue;
    // To preserve case: if original is lowercase and variant has uppercase first? Our fams mostly lowercase, Conduct capital. For lowercase original, lower the variant? But variants are already correct case for lowercase. For safety, if original is all lower, use v.toLowerCase()? But v already lower. If original capitalized, capitalize v. Let's handle:
    let rep=v;
    // if original word is lowercase, ensure rep is lowercase (in case fam has capital like Conduct)
    // if original is Capitalized (First upper rest lower), capitalize rep
    if(/^[a-z]+$/.test(o.word)){
      // original all lower -> make rep all lower? but rep may be like \"Behavior\" -> should be \"behavior\"?
      // However Conduct family all capitalized, but para2/6 have no Conduct, so ignore.
      // We'll just use rep as-is if rep is lower, else lower it?
      if(rep!==rep.toLowerCase() && o.word===o.word.toLowerCase()){
        rep=rep.toLowerCase();
      }
    } else if(/^[A-Z][a-z]+$/.test(o.word)){
      rep=rep.charAt(0).toUpperCase()+rep.slice(1).toLowerCase();
      // Actually need to handle? For now.
    }
    if(rep===o.word) continue;
    let newText=baseText.slice(0,o.index)+rep+baseText.slice(o.index+o.len);
    let score=getOverfulls(newText);
    if(score.count<baseScore.count || (score.count===baseScore.count && score.excess<baseScore.excess-0.01)){
      console.log(`IMPROVE cand ${i} ${o.word}@${o.index}(para${o.para}) -> ${rep} : count ${score.count} excess ${score.excess.toFixed(2)} details: ${score.details.replace(/\n/g,' | ')}`);
      results.push({i, from:o.word, to:rep, index:o.index, score});
    }
  }
}
console.log('done single sweep, improvements:',results.length);
// restore base
fs.writeFileSync('input.tex',baseText);
","path":"solver.js"}

